//! Smallest feasible preauthorized composition; task/effect scope never expands.
use crate::{domain::*,error::{Error,Result},scheduler::*,model_pool::{Policy as ModelPolicy,State as ModelState}};
use serde::{Serialize,Deserialize};
#[derive(Clone,Debug,Serialize,Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RoleProfile {pub role:Role,pub profile:String}
#[derive(Clone,Debug,Serialize,Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Policy {pub initial:Mode,#[serde(default)]pub allowed:Vec<Mode>,pub agent_ceiling:u32,pub coordination:Option<bool>,pub review:Option<bool>,pub director:Option<bool>,pub tokens_per_actor:u64,pub steps_per_actor:u32,pub cost_per_actor:u64,pub max_transitions:u32,#[serde(default)]pub role_profiles:Vec<RoleProfile>,#[serde(default="two")]pub mesh_peers:u32}
fn two()->u32{2}
impl Policy {pub fn validate(&self,actors:usize)->Result<()>{if self.coordination==Some(true)&&!matches!(self.initial,Mode::Pair|Mode::Crew|Mode::Fleet)||self.review==Some(true)&&!matches!(self.initial,Mode::Crew|Mode::Fleet)||self.director==Some(true)&&self.initial!=Mode::Fleet{return Err(Error::Invalid);}if self.initial==Mode::Adaptive||self.allowed.len()>5||self.allowed.iter().any(|m|*m==Mode::Adaptive)||self.agent_ceiling==0||self.agent_ceiling>32||actors>self.agent_ceiling as usize||self.tokens_per_actor==0||self.steps_per_actor==0||self.max_transitions>8||self.mesh_peers==0||self.mesh_peers>32||self.role_profiles.len()>5{return Err(Error::Invalid);}Ok(())}}
fn roles(mode:&Mode,peers:u32)->Vec<Role>{match mode{Mode::Solo=>vec![Role::Independent],Mode::Pair=>vec![Role::Lead,Role::Operator],Mode::Crew=>vec![Role::Lead,Role::Reviewer,Role::Operator],Mode::Fleet=>vec![Role::Director,Role::Lead,Role::Reviewer,Role::Operator],Mode::Mesh=>vec![Role::Independent;peers as usize],Mode::Adaptive=>vec![]}}
pub fn derive(graph:&Graph,mode:Mode,peers:u32)->Result<Graph>{
    if graph.nodes.iter().any(|n|n.lease.is_some()||matches!(n.state,Status::Running|Status::Reconciling|Status::WaitingInput))||graph.plan.agents.iter().any(|a|!a.skills.is_empty()){return Err(Error::Denied);}
    let mut wanted=roles(&mode,peers);for role in [Role::Operator,Role::Reviewer]{if matches!((&mode,&role),(Mode::Crew,Role::Operator)|(Mode::Fleet,Role::Operator|Role::Reviewer)){let busy=graph.plan.agents.iter().filter(|a|a.role==role&&graph.nodes.iter().any(|n|n.task.actor==a.id&&n.task.kind!=Kind::Coordinate&&n.fence>0)).count();let current=wanted.iter().filter(|r|**r==role).count();wanted.extend(std::iter::repeat_n(role,busy.saturating_sub(current)));}}let mut agents=vec![];let mut used=vec![];
    for role in wanted{let existing=graph.plan.agents.iter().filter(|a|a.role==role&&!used.contains(&a.id)).min_by_key(|a|(!graph.nodes.iter().any(|n|n.task.actor==a.id&&n.task.kind!=Kind::Coordinate&&n.fence>0),a.id.0));let id=existing.map(|a|a.id).unwrap_or_default();used.push(id);agents.push(Agent{id,role,reports_to:None,skills:vec![]});}
    if graph.nodes.iter().any(|n|n.task.kind!=Kind::Coordinate&&n.fence>0&&!used.contains(&n.task.actor)){return Err(Error::Denied);}
    let find=|role:&Role|agents.iter().find(|a|&a.role==role).map(|a|a.id).ok_or(Error::Invalid);let root_actor=match mode{Mode::Solo|Mode::Mesh=>find(&Role::Independent)?,Mode::Fleet=>find(&Role::Director)?,_=>find(&Role::Lead)?};let lead=if mode==Mode::Fleet{Some(find(&Role::Lead)?)}else if matches!(mode,Mode::Pair|Mode::Crew){Some(root_actor)}else{None};
    let roster=agents.clone();for agent in &mut agents{agent.reports_to=match agent.role{Role::Lead if mode==Mode::Fleet=>Some(root_actor),Role::Operator|Role::Reviewer=>lead,_=>None};}
    let mut plan=graph.plan.clone();plan.mode=mode.clone();plan.agents=agents;let root=plan.root().id;
    for task in &mut plan.tasks{let prior=graph.node(task.id)?;if task.kind!=Kind::Coordinate&&prior.fence>0{if !roster.iter().any(|a|a.id==prior.task.actor){return Err(Error::Denied);}task.actor=prior.task.actor;continue;}task.actor=match &task.kind{Kind::Coordinate=>if task.id==root{root_actor}else{lead.unwrap_or(root_actor)},Kind::Coding=>if matches!(mode,Mode::Solo|Mode::Mesh){root_actor}else{roster.iter().find(|a|a.role==Role::Operator).ok_or(Error::Invalid)?.id},Kind::Review{..}=>roster.iter().find(|a|a.role==Role::Reviewer).ok_or(Error::Invalid)?.id};}
    plan.recipients=if mode==Mode::Mesh{plan.agents.iter().flat_map(|a|plan.agents.iter().filter(move|b|b.id!=a.id).map(move|b|(a.id,b.id))).collect()}else{plan.agents.iter().filter_map(|a|a.reports_to.map(|p|[(a.id,p),(p,a.id)])).flatten().collect()};plan.validate()?;
    let mut result=graph.clone();result.plan=plan;for node in &mut result.nodes{let previous=graph.node(node.task.id)?;node.task=result.plan.tasks.iter().find(|t|t.id==node.task.id).ok_or(Error::State)?.clone();node.revision+=1;node.owner_assigned=mode!=Mode::Mesh||node.task.kind!=Kind::Coding||previous.owner_assigned&&previous.task.actor==node.task.actor;}Ok(result)
}
/// Actual hard reservations still apply after these explicit planning estimates.
pub fn choose(graph:&Graph,model:&ModelState,tokens:u64,steps:u64,cost:u64)->Result<Option<(Graph,Vec<String>)>>{
    let Some(policy)=&model.policy.adaptive else{return Ok(None);};policy.validate(graph.plan.agents.len())?;
    if policy.allowed.is_empty()||policy.coordination.is_none()||policy.review.is_none()||policy.director.is_none()||model.adaptations>=policy.max_transitions{return Ok(None);}
    let mut candidates=vec![];
    for (order,mode) in policy.allowed.iter().enumerate(){let mut roles=roles(mode,policy.mesh_peers);for role in [Role::Operator,Role::Reviewer]{if matches!((mode,&role),(Mode::Crew,Role::Operator)|(Mode::Fleet,Role::Operator|Role::Reviewer)){let busy=graph.plan.agents.iter().filter(|a|a.role==role&&graph.nodes.iter().any(|n|n.task.actor==a.id&&n.task.kind!=Kind::Coordinate&&n.fence>0)).count();let current=roles.iter().filter(|r|**r==role).count();roles.extend(std::iter::repeat_n(role,busy.saturating_sub(current)));}}if roles.len()>policy.agent_ceiling as usize||policy.coordination==Some(true)&&!roles.contains(&Role::Lead)||policy.review==Some(true)&&!roles.contains(&Role::Reviewer)||policy.director==Some(true)&&!roles.contains(&Role::Director){continue;}
        let count=roles.len() as u64;if count.checked_mul(policy.tokens_per_actor).is_none_or(|n|n>tokens)||count.checked_mul(policy.steps_per_actor as u64).is_none_or(|n|n>steps)||count.checked_mul(policy.cost_per_actor).is_none_or(|n|n>cost){continue;}
        let Ok(candidate)=derive(graph,mode.clone(),policy.mesh_peers)else{continue;};let single=model.policy.assignments.first().filter(|id|model.policy.assignments.iter().all(|v|v==*id));let mut assignments=vec![];let mut valid=true;for agent in &candidate.plan.agents{if let Some(p)=policy.role_profiles.iter().find(|p|p.role==agent.role){assignments.push(p.profile.clone());}else if let Some(id)=single{assignments.push(id.clone());}else{valid=false;break;}}if !valid{continue;}
        let mut allocation:ModelPolicy=model.policy.clone();allocation.assignments=assignments.clone();if allocation.validate(candidate.plan.agents.len(),candidate.nodes.len()).is_err(){continue;}let mut estimate=model.clone();estimate.policy=allocation;estimate.reservations.clear();let Ok((mut ram,mut vram))=estimate.usage()else{continue;};let mut instances=std::collections::HashSet::new();for id in &assignments{let p=estimate.policy.profile(id)?;if instances.insert(&p.instance){let n=assignments.iter().filter(|id|estimate.policy.profile(id).is_ok_and(|other|other.instance==p.instance)).count().min(p.slots as usize) as u64;let ctx=p.provider.context_tokens.ok_or(Error::Unsupported)? as u64;ram=ram.checked_add(ctx.checked_mul(p.kv_ram_per_token).and_then(|x|x.checked_mul(n)).unwrap_or(u64::MAX)).unwrap_or(u64::MAX);vram=vram.checked_add(ctx.checked_mul(p.kv_vram_per_token).and_then(|x|x.checked_mul(n)).unwrap_or(u64::MAX)).unwrap_or(u64::MAX);}}
        if ram>estimate.policy.limits.ram||vram>estimate.policy.limits.vram{continue;}candidates.push((candidate.plan.agents.len(),usize::from(*mode!=graph.plan.mode),order,candidate,assignments));
    }
    candidates.sort_by_key(|c|(c.0,c.1,c.2));let Some((_,_,_,candidate,assignments))=candidates.into_iter().next()else{return Err(Error::Denied);};if candidate.plan.mode==graph.plan.mode&&candidate.plan.agents.len()==graph.plan.agents.len(){return Ok(None);}Ok(Some((candidate,assignments)))
}
